@pydantic.dataclasses.dataclass(
    frozen=True,
    kw_only=True,
    config=ConfigDict(arbitrary_types_allowed=True, extra="forbid"),
)
class JointGoal:
    """A part joint's position at least or at most :attr:`value`: a length
    along a slide or an angle about a hinge, from the part's scanned pose,
    where the joint reads zero.

    :raises ValueError: When :attr:`value` and :attr:`range` are not all
        lengths or all angles, the range is empty, or the value lies outside
        it.
    """

    #: Which side of :attr:`value` the goal lies on.
    bound: Literal["at_least", "at_most"]
    #: The position the goal is bounded by.
    value: SignedMm | SignedDeg
    #: The joint's travel, from its low stop to its high stop, over which
    #: :meth:`left` measures how far the joint has to go.
    range: tuple[SignedMm | SignedDeg, SignedMm | SignedDeg]

    def __post_init__(self) -> None:
        dimensions = {unxt.dimension_of(q) for q in (self.value, *self.range)}
        if len(dimensions) != 1:
            raise ValueError(
                f"a joint goal's value and range share one dimension, not {dimensions}"
            )
        low, high = self.travel
        if not low < high:
            raise ValueError(f"a joint goal's range {self.range} is empty")
        if not low <= self.position <= high:
            raise ValueError(
                f"a joint goal of {self.value} lies outside its range {self.range}"
            )

    @property
    def units(self) -> Literal["m", "rad"]:
        """The joint's own units: metres along a slide, radians about a hinge."""
        if unxt.dimension_of(self.value) == unxt.dimension("length"):
            return "m"
        return "rad"

    # The rollouts' cost reads these for every sampled state, so each
    # quantity converts once.
    @cached_property
    def position(self) -> float:
        """:attr:`value` in the joint's own units: metres or radians."""
        return _joint_units(self.value)

    @cached_property
    def travel(self) -> tuple[float, float]:
        """:attr:`range` in the joint's own units: metres or radians."""
        low, high = self.range
        return _joint_units(low), _joint_units(high)

    def left(self, position: float) -> float:
        """How far a joint at ``position``, in its own units, is from the
        goal, as a share of its travel: zero at the goal or past it."""
        low, high = self.travel
        short = (
            self.position - position
            if self.bound == "at_least"
            else position - self.position
        )
        return max(0.0, short) / (high - low)


@pydantic.dataclasses.dataclass(
    frozen=True,
    kw_only=True,
    config=ConfigDict(arbitrary_types_allowed=True, extra="forbid"),
)
class Actuate:
    """A stage that carries the lifted tool as a :class:`Lift` does while it
    drives the joint of the tool's part :attr:`part` to :attr:`goal`, adding
    :attr:`charge` times the share of the joint's travel left to it; the
    stage's hold also needs the goal met (:meth:`reached`).

    Its seed carries the tool as the lift seed does while the closing joints
    squeeze at the servo cap, so a pad resting on the part presses it as
    hard as its servos let it.
    """

    #: The part's label in its tool's split
    #: (:class:`~robotl.examples.ycb_artifacts.ToolSplit`).
    part: str
    #: Where the part's joint has to be.
    goal: JointGoal
    #: Cost of the joint's whole travel left to :attr:`goal`.
    charge: PositiveFloat
    #: Which way the tool points while it is actuated, or None for any way.
    pointing: PoseGoal | None = None

    @property
    def hold(self) -> Hold:
        """The carried hold, pointing within :attr:`pointing`."""
        return Hold(pose=self.pointing)

    def escape_drift(self, grasp: "ScrewdriverGrasp", data: mujoco.MjData) -> float:
        """The tool's distance from where it was when the stage began."""
        return grasp.drift(data)

    def restraint(
        self, grasp: "ScrewdriverGrasp", data: mujoco.MjData, secured: float
    ) -> float:
        return grasp.restrained(data, secured)

    def carry(
        self, grasp: "ScrewdriverGrasp", hand_fraction: float, external_fraction: float
    ) -> float:
        return grasp.carry(hand_fraction, external_fraction)

    def extend(
        self,
        grasp: "ScrewdriverGrasp",
        data: mujoco.MjData,
        observation: PalmObservation,
        terms: dict[str, float],
    ) -> dict[str, float]:
        """``terms`` with the tool's own lift terms and :attr:`charge` for
        the share of the joint's travel left to :attr:`goal`."""
        left = self.goal.left(grasp.joint(data, self.part))
        return grasp.lift_stage_terms(data, observation, terms) | {
            "actuate": self.charge * left
        }

    def measurements(self, grasp: "ScrewdriverGrasp", data: mujoco.MjData) -> dict:
        """Nothing beyond the grasp's own, which read the part joints."""
        return {}

    def pose(
        self, grasp: "ScrewdriverGrasp", data: mujoco.MjData
    ) -> tuple[Array, Array]:
        """Palm position and rotation of the tool's own lift seed."""
        return grasp.lifting_pose(data)

    def controls(
        self, grasp: "ScrewdriverGrasp", data: mujoco.MjData, grid: Array, arm: Array
    ) -> Array:
        """Controls that carry the tool toward ``arm`` over the horizon while
        the closing joints squeeze."""
        return grasp.squeezed_controls(data, grid, arm, 1.0)

    def reached(self, grasp: "ScrewdriverGrasp", data: mujoco.MjData) -> bool:
        """Whether the part's joint meets :attr:`goal`."""
        return self.goal.left(grasp.joint(data, self.part)) == 0.0


